#include <bits/stdc++.h>
using namespace std;

int main() {
	int t;
	cin >> t;
	
	while(t--){
	    int n ;
	    cin >> n ;
	    
	    int maxi = 3*n;
	    
	    vector<long long>a(maxi);
	    
	    for(int i = 0 ; i < maxi ; i++){
	        cin >> a[i];
	    }
	    
	    sort(a.rbegin(),a.rend());
	    
	    vector<long long>pref(maxi+1,0);
	    for(int i = 0 ; i < maxi ; i++){
	        pref[i+1]=pref[i]+a[i];
	    }
	    
	    long long ans = 0 ;
	    
	    for(long long k = 0 ; k <= n ; k++){
	        long long left = 0 ;
	        long long right = n-k;
	        
	        while(right-left>=3){
	            long long m1 = left+(right-left)/3;
	            long long m2 = right-(right-left)/3;
	            long long v1 = pref[k+2*m1]+3LL*pref[maxi-2*k-m1];
	            long long v2 = pref[k+2*m2]+3LL*pref[maxi-2*k-m2];
	            
	            if(v1<v2){
	                left=m1;
	            }else{
	                right=m2;
	            }
	        }
	        
	        for(long long t = left ; t<=right ; t++){
	            long long temp = 2LL*pref[k]+pref[k+2*t]+3LL*pref[maxi-2*k-t];
	            if(temp>ans){
	                ans=temp;
	            }
	        }
	    }
	    
	    cout << ans << endl;
	    
	    
	}

}
